        [Str.HelpTitle] = "Справка",
        [Str.HelpStartH] = "Начало работы",
        [Str.HelpStartBody] = "Откройте Синхронизации → Добавить синхронизацию и укажите сервис, ID и пароль либо отсканируйте QR браузера. Закладки шифруются на устройстве; сервер не может их прочитать. Забытый пароль восстановить нельзя.",
        [Str.HelpAddH] = "Добавление закладок",
        [Str.HelpAddBody] = "Нажмите «Добавить», чтобы создать закладку или папку. Также можно поделиться страницей из браузера или другого приложения с Keepmark, чтобы сохранить её.",
        [Str.HelpSyncH] = "Синхронизация",
        [Str.HelpSyncBody] = "Изменения синхронизируются автоматически при подключении, пока приложение видно на экране; Синхронизировать запускает дополнительную проверку. Меню, Другие и Панель закладок включены всегда. Перед активацией другой синхронизации приложение сохраняет текущую; ошибка сети или конфликт блокируют переход. Во время перехода редактирование заблокировано. При конфликте выберите копию сервера, локальную копию или объединение.",
        [Str.HelpBackupH] = "Резервные копии и отмена",
        [Str.HelpBackupBody] = "Страховочные копии защищают явную перезапись, импорт, восстановление, смену пароля и очистку дубликатов. Обычная синхронизация также сохраняет заменяемую сторону перед изменением более 10 элементов. Если создание необходимой копии не удаётся, операция останавливается. Удаление выделенных элементов создаёт копию; множественное удаление восстанавливается через Резервная копия → Страховочные копии. Одиночное удаление и перемещения предлагают Отменить на шесть секунд. Обычный переход сохраняет прежнюю синхронизацию на её сервере без копии перехода. Можно также экспортировать зашифрованный файл.",
        [Str.HelpToolsH] = "Дубликаты и синхронизации",
